-- Count rows per zoneref in site_combined
WITH 
pc AS (
    SELECT s.zoneref, COUNT(*) as cnt FROM pointcloud p JOIN scans s ON p.crewref = s.crewref AND p.arcref = s.arcref GROUP BY s.zoneref
),
mesh_zones AS (
    SELECT DISTINCT zoneref FROM mesh
),
reg_zones AS (
    SELECT DISTINCT s.zoneref FROM registration r JOIN projects p ON r.arcref = p.arcregistry JOIN scans s ON s.arcref = p.arcregistry
),
site_pc_agg AS (
    SELECT s.zoneref, AVG(CAST(p.cloud_metrics->>'Cover_Pct' AS numeric)) as avg_cover
    FROM pointcloud p JOIN scans s ON p.crewref = s.crewref AND p.arcref = s.arcref
    GROUP BY s.zoneref
),
site_mesh_agg AS (
    SELECT DISTINCT m.zoneref FROM mesh m
),
site_reg_agg AS (
    SELECT DISTINCT s.zoneref FROM registration r JOIN projects p ON r.arcref = p.arcregistry JOIN scans s ON s.arcref = p.arcregistry
)
SELECT COUNT(*) FROM site_pc_agg FULL OUTER JOIN site_mesh_agg ON site_pc_agg.zoneref = site_mesh_agg.zoneref FULL OUTER JOIN site_reg_agg ON COALESCE(site_pc_agg.zoneref, site_mesh_agg.zoneref) = site_reg_agg.zoneref;
